(function(root){
const LINES=[{id:'sinnamwon-uiryeong',name:'345KV 신남원-의령',count:136},{id:'sabong-gaeyang',name:'154KV 사봉-개양',count:56}];
const LAMP_KEYS=['upperSupply','upperLoad','lowerSupply','lowerLoad'];
const lampIntensity=(units)=>['고광도','중광도','저광도'].find(v=>LAMP_KEYS.some(k=>units?.[k]===v))||'';
const validNumbers=g=>['1','2'].includes(g.leftNo)&&['1','2'].includes(g.rightNo)&&g.leftNo!==g.rightNo;
const sharedPart=p=>['철탑 기본정보','가공지선','지형','부지','항공등','항공구','피뢰기','애자련'].includes(p);
const PARTS=['철탑 기본정보','가공지선','애자련','피뢰기','항공구','항공등','지형','부지'];
const CHOICES={'피뢰기':['#1','#2'],'항공등':['고광도','중광도','저광도'],'애자련':['내장','현수'],'지형':['산악지','논','도심지']};
const migrate=r=>({...r,lineId:r.lineId||LINES[0].id,land:Array.isArray(r.land)?r.land.map(value=>value==='칡밭'?'칡넝쿨':value):r.land});
function latest(records,lineId,tower,part){return records.filter(r=>r.lineId===lineId&&r.tower===tower&&r.part===part).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt))[0];}
function groundLabel(g){return !g?'미등록':g.count===1?'1조 · '+'중앙 '+g.single:'2조 · 좌 '+g.left+' / 우 '+g.right;}
function validGround(g){return !!g&&g.direction==='1호→2호 정방향'&&(g.count===1?['좌측','중앙','우측'].includes(g.position)&&['OPGW','GW'].includes(g.single):g.count===2&&['OPGW','GW'].includes(g.left)&&['OPGW','GW'].includes(g.right));}
function arresterLocations(record){return record?.arresterCircuits??(record?.arresterCircuit?[record.arresterCircuit]:[]);}
function validBallCircuits(rows,total){
  return Array.isArray(rows)&&rows.length===2&&rows.every(row=>row&&Number.isInteger(row.count)&&row.count>=0&&row.count<=100&&(['white','orange'].includes(row.color)||(row.count===0&&row.color==='')))&&rows[0].count+rows[1].count===total;
}
function ballLabel(record){
  if(!Number.isInteger(record.ballCount))return '개수 미등록';
  const total=record.ballCount+'개';
  if(!record.ballCircuits)return total;
  return total+' · '+record.ballCircuits.map((row,index)=>'#'+(index+1)+' '+row.count+'개'+(row.color?' '+(row.color==='white'?'흰색':'주황색'):'')).join(' / ');
}
function label(r){if(!r)return '미등록';if(r.part==='피뢰기')return arresterLocations(r).join(' · ')||'미설치';if(r.part==='철탑 기본정보')return [r.towerType,r.towerHeight?r.towerHeight+' m':''].filter(Boolean).join(' · ')||'미등록';if(r.part==='가공지선')return groundLabel(r.groundWires);if(r.part==='항공구')return ballLabel(r);if(r.part==='항공등')return r.lampUnits?['상부','하부'].map((p,i)=>p+' 전원 '+(r.lampUnits[LAMP_KEYS[i*2]]||'미확인')+' / 부하 '+(r.lampUnits[LAMP_KEYS[i*2+1]]||'미확인')).join(' · '):r.lightIntensity||'광도 미등록';if(r.part==='애자련')return (r.insulatorType||'형태 미등록')+' · '+(r.stringCount?r.stringCount+'련':'련수 미등록')+(r.insulatorYear?' · '+r.insulatorYear+'년':'')+(r.insulatorDiscs?' · 1련당 '+r.insulatorDiscs+'장':'');if(r.part==='지형')return r.terrain||'미등록';return r.land?.join(', ')||'미등록';}
function scene(records,lineId,tower){const lamp=latest(records,lineId,tower,'항공등');const info=latest(records,lineId,tower,'철탑 기본정보');const balls=latest(records,lineId,tower,'항공구');return {towerType:info?.towerType,towerHeight:info?.towerHeight,groundWires:latest(records,lineId,tower,'가공지선')?.groundWires,ballCount:balls?.ballCount??0,ballCircuits:balls?.ballCircuits,lampUnits:lamp?.lampUnits,lightIntensity:lamp?.lampUnits?lampIntensity(lamp.lampUnits):lamp?.lightIntensity||'',insulatorType:latest(records,lineId,tower,'애자련')?.insulatorType||'',stringCount:latest(records,lineId,tower,'애자련')?.stringCount,terrain:latest(records,lineId,tower,'지형')?.terrain||''};}
function validate(data){if(data?.format!=='tower-ledger'||![1,2,3,4,5].includes(data.version)||!Array.isArray(data.records))throw Error('지원하지 않는 백업 형식입니다.');const ids=new Set();const records=data.records.map(r=>{if(data.version<3)r=migrate(r);const line=LINES.find(l=>l.id===r?.lineId);if(!line||typeof r.id!=='string'||!r.id||ids.has(r.id)||!Number.isInteger(r.tower)||r.tower<1||r.tower>line.count||!PARTS.includes(r.part)||typeof r.note!=='string'||r.note.length>3000||!Array.isArray(r.land)||!r.land.every(v=>['도심지','칡밭','칡넝쿨','산지','농경지','기타'].includes(v))||!Array.isArray(r.photos)||r.photos.length>8||!r.photos.every(v=>typeof v==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(v))||typeof r.createdAt!=='string'||!Number.isFinite(Date.parse(r.createdAt)))throw Error('백업 기록이 올바르지 않습니다.');for(const [field,p] of [['lightIntensity','항공등'],['insulatorType','애자련'],['terrain','지형']])if(r[field]!==undefined&&r[field]!==''&&!CHOICES[p].includes(r[field]))throw Error('선택값이 올바르지 않습니다.');if(r.ballCount!==undefined&&(!Number.isInteger(r.ballCount)||r.ballCount<0||r.ballCount>100))throw Error('항공구 개수는 0~100개입니다.');if(r.stringCount!==undefined&&![1,2].includes(r.stringCount))throw Error('애자련은 1련 또는 2련입니다.');if(r.groundWires!==undefined&&!validGround(r.groundWires))throw Error('가공지선 구성과 방향을 확인해주세요.');if(data.version===4&&r.part==='가공지선'&&!validGround(r.groundWires))throw Error('가공지선 정보가 없습니다.');if(r.groundWires?.count===2&&(r.groundWires.leftNo||r.groundWires.rightNo)&&!validNumbers(r.groundWires))throw Error('가공지선 번호를 확인해주세요.');if(r.lampUnits&&(!LAMP_KEYS.every(k=>['','미설치',...CHOICES['항공등']].includes(r.lampUnits[k]))))throw Error('항공등 광도를 확인해주세요.');for(const [v,min,max] of [[r.insulatorYear,1900,9999],[r.insulatorDiscs,1,999]])if(v!==undefined&&(!Number.isInteger(v)||v<min||v>max))throw Error('애자련 연도와 장수를 확인해주세요.');if(r.circuit!==undefined&&![1,2].includes(r.circuit))throw Error('회선 번호를 확인해주세요.');if(r.towerType!==undefined&&(typeof r.towerType!=='string'||r.towerType.length>60))throw Error('철탑 형태를 확인해주세요.');if(r.towerHeight!==undefined&&(!Number.isFinite(r.towerHeight)||r.towerHeight<0.01||r.towerHeight>999))throw Error('철탑 높이를 확인해주세요.');if(r.part==='피뢰기'&&!(r.arresterCircuits===undefined?CHOICES['피뢰기'].includes(r.arresterCircuit):Array.isArray(r.arresterCircuits)&&new Set(r.arresterCircuits).size===r.arresterCircuits.length&&r.arresterCircuits.every(value=>CHOICES['피뢰기'].includes(value))))throw Error('피뢰기 설치 회선을 확인해주세요.');if(r.ballCircuits!==undefined&&!validBallCircuits(r.ballCircuits,r.ballCount))throw Error('회선별 항공구 개수와 색상을 확인해주세요.');ids.add(r.id);return migrate(r);});return records;}
const api={LINES,PARTS,CHOICES,migrate,latest,label,scene,validate,groundLabel,validGround,validNumbers,LAMP_KEYS,lampIntensity,sharedPart,arresterLocations,ballLabel,validBallCircuits};if(typeof module!=='undefined')module.exports=api;else root.LedgerModel=api;
})(globalThis);
